/**
 * GET /talk/:clientId/:language — a public, link-shareable page letting
 * anyone test the voice assistant via a browser mic call. No internal
 * config is exposed: just the clinic's own (already-public) name and a
 * Talk button.
 *
 * Unlike generateTestPage.ts's internal QA tool (pre-baked static files,
 * regenerated by hand after every `vapi:sync --apply`), this renders
 * dynamically per request straight from the current Vapi state file, so it
 * can never go stale.
 */
import { Router, json, type NextFunction, type Request, type Response } from 'express';
import { z } from 'zod';

import { ClientConfigError, loadClient } from '../config/loadClient.js';
import type { ClientConfig } from '../config/schema.js';
import { logger } from '../lib/logger.js';
import { fillClinicPlaceholders, pick } from '../vapi/promptTemplate.js';
import { normalizeCallerPhone } from '../lib/callerPhone.js';
import type { PriorCallReader } from '../repositories/callLogRepository.js';
import {
  decideTalkCall,
  remainingTalkCalls,
  talkCallCookieName,
  TALK_CALL_COOKIE_MAX_AGE_MS,
  TALK_MAX_CALL_DURATION_SECONDS,
} from '../middleware/talkCallLimit.js';
import {
  CALLER_PHONE_VARIABLE,
  PRIOR_CALL_VARIABLE,
  formatPriorCall,
} from '../vapi/callVariables.js';
import {
  assistantResourceName,
  renderOpeningMessage,
  renderTalkSquad,
  squadMemberIds,
  startsWithSquad,
} from '../vapi/squad.js';
import { readState } from '../vapi/stateStore.js';
import { renderTalkBootstrapScript, renderTalkPage } from '../vapi/talkPage.js';

export const TALK_URL_PREFIX = '/talk';

export interface TalkRouterOptions {
  /** Vapi's public key — safe to expose in the browser (VAPI-FACTS.md). */
  publicKey: string;
  /** Signs the per-visitor call-count cookie (VP-9, src/middleware/talkCallLimit.ts). */
  rateLimitSecret: string;
  /** Shared secret for the owner/staff `?key=` bypass link (VP-9). */
  bypassKey: string;
  /** Mirrors the staff session cookie's `secure` flag (VP-9). */
  isProduction: boolean;
  /** Returning-caller lookup (VP-15): the caller's most recent earlier call, by phone number. */
  callLogs: PriorCallReader;
  /** Random source for the opening-line rotation; tests pass a fixed one. Defaults to Math.random. */
  random?: () => number;
  /** Overrides for tests: where the client configs / Vapi state files are resolved from. */
  clientsDir?: string;
  repoRoot?: string;
}

/**
 * How a call from this page starts: the default language starts the whole squad (it can hand off
 * to the others, VP-22); any other language starts its own assistant directly.
 */
type TalkStart =
  | { kind: 'assistant'; assistantId: string }
  | { kind: 'squad'; assistantIds: Readonly<Record<string, string>> };

interface ResolvedTarget {
  config: ClientConfig;
  language: string;
  start: TalkStart;
}

/**
 * Undefined for any reason at all — an unknown clientId, an unsupported language, or a language
 * (for the squad start: any squad member) never synced. No `language` means the client's default.
 */
function resolveTarget(
  clientId: string,
  language: string | undefined,
  options: TalkRouterOptions,
): ResolvedTarget | undefined {
  let config: ClientConfig;
  try {
    config = loadClient(clientId, options.clientsDir ? { clientsDir: options.clientsDir } : {});
  } catch (error) {
    if (error instanceof ClientConfigError) return undefined;
    throw error;
  }

  const target = language ?? config.languages.default;
  if (!config.languages.supported.includes(target)) return undefined;

  const state = readState(clientId, options.repoRoot ? { repoRoot: options.repoRoot } : {});
  const idOf = (memberId: string): string | undefined =>
    state.assistants[assistantResourceName(clientId, memberId)];

  if (startsWithSquad(config, target)) {
    const members = squadMemberIds(config).flatMap((memberId) => {
      const assistantId = idOf(memberId);
      return assistantId ? [[memberId, assistantId] as const] : [];
    });
    if (members.length !== squadMemberIds(config).length) return undefined;
    return {
      config,
      language: target,
      start: { kind: 'squad', assistantIds: Object.fromEntries(members) },
    };
  }

  const assistantId = idOf(target);
  if (!assistantId) return undefined;
  return { config, language: target, start: { kind: 'assistant', assistantId } };
}

/** rules.ts's languageIssues check guarantees business.name has every supported language on a validated config. */
function clinicNameOf(config: ClientConfig, language: string): string {
  const name = config.business.name[language];
  if (!name) {
    throw new Error(`business.name missing "${language}" despite passing validation — config bug`);
  }
  return name;
}

/**
 * One of the language's configured "how can I help?" wordings, chosen at random. Undefined when
 * there is nothing to rotate (fewer than two wordings), so such a client keeps its saved greeting.
 */
function pickOpeningQuestion(
  config: ClientConfig,
  language: string,
  random: () => number,
): string | undefined {
  const questions = config.languages.settings[language]?.openingQuestions;
  if (!questions || questions.length < 2) return undefined;
  return questions[Math.min(questions.length - 1, Math.floor(random() * questions.length))];
}

/** The language's own endpoints (page alias, bootstrap script, calls) — always carries the language. */
function pagePath(clientId: string, language: string): string {
  return `${TALK_URL_PREFIX}/${clientId}/${language}`;
}

/** The shareable page URL: the default language lives at the plain URL, the others under it (VP-22). */
function shareablePath(config: ClientConfig, language: string): string {
  return language === config.languages.default
    ? `${TALK_URL_PREFIX}/${config.clientId}`
    : pagePath(config.clientId, language);
}

/** The demo page's phone field (VP-15). Validation of the number itself is normalizeCallerPhone. */
const callBodySchema = z.object({ callerPhone: z.string().max(40) });

export function talkRouter(options: TalkRouterOptions): Router {
  const router = Router();

  // One language's page (`requested` undefined = the client's default). Shared by the plain URL
  // and the language URLs; either way the page loads its own language's bootstrap script and
  // calls endpoint, so the default-language page starts the squad (VP-22).
  const servePage = (
    req: Request,
    res: Response,
    next: NextFunction,
    clientId: string,
    requested: string | undefined,
  ): void => {
    const resolved = resolveTarget(clientId, requested, options);
    if (!resolved) {
      next();
      return;
    }
    const { language } = resolved;

    const switchLinks = resolved.config.languages.supported
      .filter((code) => code !== language)
      .map((code) => ({
        label: clinicNameOf(resolved.config, code),
        href: shareablePath(resolved.config, code),
      }));
    const key = typeof req.query.key === 'string' ? req.query.key : undefined;

    const callsRemaining = remainingTalkCalls(clientId, req.headers.cookie, key, {
      rateLimitSecret: options.rateLimitSecret,
      bypassKey: options.bypassKey,
    });

    res.type('html').send(
      renderTalkPage({
        ...(callsRemaining !== undefined ? { callsRemaining } : {}),
        clinicName: clinicNameOf(resolved.config, language),
        language,
        switchLinks,
        scriptSrc: `${pagePath(clientId, language)}/bootstrap.js`,
        ...(key !== undefined ? { bypassKey: key } : {}),
      }),
    );
  };

  router.get('/:clientId', (req: Request, res: Response, next: NextFunction) => {
    const { clientId } = req.params as { clientId: string };
    servePage(req, res, next, clientId, undefined);
  });

  router.get('/:clientId/:language', (req: Request, res: Response, next: NextFunction) => {
    const { clientId, language } = req.params as { clientId: string; language: string };
    servePage(req, res, next, clientId, language);
  });

  router.get('/:clientId/:language/bootstrap.js', (req: Request, res: Response, next) => {
    const { clientId, language } = req.params as { clientId: string; language: string };
    const resolved = resolveTarget(clientId, language, options);
    if (!resolved) {
      next();
      return;
    }

    res.type('application/javascript').send(
      renderTalkBootstrapScript({
        publicKey: options.publicKey,
        callsUrl: `${pagePath(clientId, language)}/calls`,
      }),
    );
  });

  // Checked server-side on EVERY call attempt (not just hidden client-side, CLAUDE.md-style
  // reasoning applied to the work order's own instruction) — see talkCallLimit.ts for the
  // cookie-cap + bypass-key logic. Hands back the real assistant id only when allowed.
  router.post(
    '/:clientId/:language/calls',
    json({ limit: '2kb' }),
    async (req: Request, res: Response, next) => {
      const { clientId, language } = req.params as { clientId: string; language: string };
      const resolved = resolveTarget(clientId, language, options);
      if (!resolved) {
        next();
        return;
      }

      // Checked before the call cap so a typo never uses up one of the visitor's calls.
      const body = callBodySchema.safeParse(req.body);
      const callerPhone = body.success ? normalizeCallerPhone(body.data.callerPhone) : undefined;
      if (!callerPhone) {
        res.status(400).json({ status: 'error', error: 'invalid_phone' });
        return;
      }

      const providedKey = typeof req.query.key === 'string' ? req.query.key : undefined;
      const decision = decideTalkCall(clientId, req.headers.cookie, providedKey, {
        rateLimitSecret: options.rateLimitSecret,
        bypassKey: options.bypassKey,
      });

      if (!decision.allowed) {
        res.status(429).json({ status: 'error', error: 'rate_limited', callsRemaining: 0 });
        return;
      }

      if (decision.newCookieValue) {
        res.cookie(talkCallCookieName(clientId), decision.newCookieValue, {
          httpOnly: true,
          sameSite: 'lax',
          secure: options.isProduction,
          maxAge: TALK_CALL_COOKIE_MAX_AGE_MS,
          path: TALK_URL_PREFIX,
        });
      }

      // A failed lookup must never block the call: the caller is simply treated as new.
      let priorCall;
      try {
        priorCall = await options.callLogs.findLatestByPhone(clientId, callerPhone);
      } catch (error) {
        logger.error('returning-caller lookup failed', {
          clientId,
          detail: error instanceof Error ? error.message : String(error),
        });
      }
      logger.info('returning-caller lookup', { clientId, isReturning: priorCall !== undefined });

      const openingQuestion = pickOpeningQuestion(
        resolved.config,
        language,
        options.random ?? Math.random,
      );
      const openingFill = openingQuestion === undefined ? {} : { openingQuestion };
      const firstMessage = priorCall
        ? fillClinicPlaceholders(
            resolved.config,
            language,
            pick(resolved.config.scripts.returningGreeting, language),
            openingFill,
          )
        : openingQuestion === undefined
          ? undefined
          : renderOpeningMessage(resolved.config, language, openingQuestion);

      const callsRemaining =
        decision.remaining !== undefined ? { callsRemaining: decision.remaining } : {};
      const variableValues = {
        [CALLER_PHONE_VARIABLE]: callerPhone,
        [PRIOR_CALL_VARIABLE]: formatPriorCall(priorCall, resolved.config.business.hours.timezone),
      };
      // A returning caller hears a plain welcome-back instead of the saved greeting, and every
      // call can rotate the "how can I help?" wording. The greeting is spoken before the model
      // runs, so only a firstMessage override can change it. No variants configured and a new
      // caller = no override: the saved greeting plays exactly as synced.
      const greeting = firstMessage !== undefined ? { firstMessage } : {};

      if (resolved.start.kind === 'squad') {
        // The per-call values travel inside the squad itself, with the greeting on the starting
        // member only (VAPI-FACTS.md, VP-22).
        res.json({
          ...callsRemaining,
          squad: renderTalkSquad(resolved.config, resolved.start.assistantIds, {
            maxDurationSeconds: TALK_MAX_CALL_DURATION_SECONDS,
            variableValues,
            ...greeting,
          }),
        });
        return;
      }

      res.json({
        assistantId: resolved.start.assistantId,
        ...callsRemaining,
        maxDurationSeconds: TALK_MAX_CALL_DURATION_SECONDS,
        variableValues,
        ...greeting,
      });
    },
  );

  return router;
}
